const boards = [
  { company: "Auctane", token: "auctane" },
  { company: "Aircall", token: "aircallioinc" },
  { company: "Cabify", token: "cabify" },
  { company: "Ebury", token: "ebury" },
  { company: "Celonis", token: "celonis" },
  { company: "Sofico", token: "soficonv" },

  // Additional Greenhouse boards
  { company: "Scopely", token: "scopely" },
  { company: "New Relic", token: "newrelic" },
  { company: "Socialpoint", token: "spcareers" }
];

return boards.map(board => ({
  json: board
}));

const results = $input.all();

const rolePattern =
  /(\.net|c#|csharp|mulesoft|integration|integrations|full[\s-]?stack|software engineer|software developer|backend|back-end|api developer|vue\.?js)/i;

const spainPattern =
  /(\bspain\b|\bespaña\b|\bespana\b|\bES\b|madrid|barcelona|valencia|málaga|malaga|sevilla|seville|bilbao|zaragoza|alicante|granada|murcia|valladolid)/i;

const matches = [];

for (let i = 0; i < results.length; i++) {
  const response = results[i].json;
  const jobs = response.jobs || [];

  for (const job of jobs) {
    const title = job.title || "";
    const location = job.location?.name || "";

    const isTargetRole = rolePattern.test(title);
    const isSpain = spainPattern.test(location);

    if (!isTargetRole || !isSpain) continue;

    matches.push({
      json: {
        id: String(job.id),
        company: job.company_name || "Unknown Company",
        title,
        location,
        description: (job.content || "")
        .replace(/<[^>]*>/g, " ")
        .replace(/&lt;[^&]*&gt;/g, " ")
        .replace(/&[a-zA-Z0-9#]+;/g, " ")
        .replace(/\s+/g, " ")
        .trim()
        .slice(0, 8000),
        url: job.absolute_url || "",
        source: "Greenhouse",
        updated_at: job.updated_at || "",
        status: "Needs review"
      }
    });
  }
}

return matches;

const aiResults = $input.all();
const approved = [];

for (let i = 0; i < aiResults.length; i++) {
  const response = aiResults[i].json;

  if (response.error || !response.message?.content) {
    continue;
  }

  let assessment;

  try {
    assessment = JSON.parse(response.message.content);
  } catch (error) {
    continue;
  }

  const score = Number(assessment.score);
  const visa = assessment.visa_status;

  if (!Number.isFinite(score)) continue;
  if (score < 75 || score > 100) continue;

  if (![
    "explicit_support",
    "possible_unknown"
  ].includes(visa)) {
    continue;
  }

  // Recover the vacancy linked to this AI response.
  let job;

  try {
    job = $("Limit1").itemMatching(i).json;
  } catch (error) {
    throw new Error(
      "Cannot match AI result to vacancy: " +
      error.message
    );
  }

  if (!job?.id || !job?.url) {
    throw new Error(
      "Original job ID or application URL is missing"
    );
  }

  approved.push({
    json: {
      id: String(job.id),
      date: new Date().toISOString().slice(0, 10),
      company: job.company,
      title: job.title,
      location: job.location,
      score: score,
      visa_status: visa,
      summary: assessment.summary || "",
      cv_focus: assessment.cv_focus || "",
      cover_letter_draft:
        assessment.cover_letter_draft || "",
      evidence: assessment.evidence || "",
      url: job.url,
      source: job.source || "Greenhouse",
      status: "Needs review"
    },
    pairedItem: { item: i }
  });
}

return approved;

const rows=$('Filter new jobs').all().map(x=>x.json);
if(!rows.length) return [];
const esc=s=>String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const report=rows.map((r,i)=>`<tr><td style="padding:12px;border-bottom:1px solid #ddd"><strong>${i+1}. ${esc(r.title)}</strong><br>${esc(r.company)} — ${esc(r.location)}<br>Score: ${r.score}% | Visa: ${esc(r.visa_status)}<br>${esc(r.summary)}<br><strong>CV emphasis:</strong> ${esc(r.cv_focus)}<br><strong>Suggested cover letter:</strong><br>${esc(r.cover_letter_draft)}<br><a href="${esc(r.url)}">Review and apply on official career page</a></td></tr>`).join('');
return [{json:{subject:`Spain software jobs: ${rows.length} new matches for review`,html:`<h2>Spain job review queue</h2><p>No applications have been submitted. Verify work authorization, employer, and every CV claim before applying.</p><table>${report}</table><p>Update status in Google Sheets after submitting.</p>`}}];

// ============================================
// SPAIN JOB APPLICATION AGENT
// Filter New Jobs + Visa Prioritization
// ============================================

const newJobs =
  $("Keep 75+ and deduplicate").all();

const existingRows =
  $("Check existing applications").all();

// Minimum AI match score
const MIN_SCORE = 75;

// Allowed visa sponsorship classifications
const allowedVisaStatuses = [
  "explicit_support",
  "possible_unknown"
];

// Visa sponsorship priority
const visaPriority = {
  explicit_support: 0,
  possible_unknown: 1
};

// ============================================
// STEP 1: Collect existing job IDs
// ============================================

const existingIds = new Set(
  existingRows
    .map(item => String(item.json.id ?? "").trim())
    .filter(Boolean)
);

// ============================================
// STEP 2: Filter new job opportunities
// ============================================

const seenInThisRun = new Set();
const result = [];

for (const item of newJobs) {
  const job = item.json;

  const id = String(job.id ?? "").trim();
  const score = Number(job.score);
  const visaStatus = String(
    job.visa_status ?? ""
  ).trim();

  // Skip incomplete job records
  if (!id || !job.title || !job.url) {
    continue;
  }

  // Reject scores below 75%
  if (
    !Number.isFinite(score) ||
    score < MIN_SCORE ||
    score > 100
  ) {
    continue;
  }

  // Exclude restricted or unclassified visa cases
  if (!allowedVisaStatuses.includes(visaStatus)) {
    continue;
  }

  // Skip jobs already in Google Sheets
  if (existingIds.has(id)) {
    continue;
  }

  // Skip duplicates from the same execution
  if (seenInThisRun.has(id)) {
    continue;
  }

  seenInThisRun.add(id);

  // Preserve the original vacancy and AI assessment
  result.push({
    json: {
      ...job,
      id,
      score,
      visa_status: visaStatus,
      status: "Needs review"
    }
  });
}

// ============================================
// STEP 3: Prioritize visa sponsorship
// ============================================

result.sort((a, b) => {
  const visaA =
    visaPriority[a.json.visa_status] ?? 99;

  const visaB =
    visaPriority[b.json.visa_status] ?? 99;

  // Confirmed sponsorship first
  if (visaA !== visaB) {
    return visaA - visaB;
  }

  // Higher match score first
  return Number(b.json.score) -
         Number(a.json.score);
});

// ============================================
// STEP 4: Return shortlisted jobs
// ============================================

return result;

const input = $input.all();

const first = $("Daily 08:00 Spain").first();
// Identify the source from the incoming Lever job URL.
const records = input.flatMap(item => {
  const value = item.json;
  if (Array.isArray(value)) return value;
  if (Array.isArray(value.data)) return value.data;
  if (Array.isArray(value.body)) return value.body;
  return [value];
});

const rolePattern =
  /(\.net|c#|csharp|mulesoft|integration|full[\s-]?stack|software engineer|software developer|backend|back.end|api developer|vue|frontend|front.end)/i;

const spainPattern =
  /(\bspain\b|\bespaña\b|\bespana\b|\bES\b|madrid|barcelona|valencia|malaga|málaga|sevilla|bilbao|alicante|zaragoza|murcia)/i;

const normalized = [];

for (let i = 0; i < records.length; i++) {
  const job = records[i];

  if (!job.id || !job.text) continue;

  const url = job.hostedUrl || job.applyUrl || "";
  const isPrima =
    url.includes("jobs.eu.lever.co/prima/");

  const company = isPrima ? "Prima" : "Rover";
  const site = isPrima ? "prima" : "rover";

  const title = String(job.text || "");
  const location = String(
    job.categories?.location ||
    job.categories?.allLocations?.join(", ") ||
    job.country ||
    ""
  );

  if (!rolePattern.test(title)) continue;
  if (!spainPattern.test(location)) continue;

  const description = [
    job.descriptionPlain,
    job.openingPlain,
    job.descriptionBodyPlain,
    job.additionalPlain,
    ...(job.lists || []).map(x => x.content || "")
  ].filter(Boolean).join(" ");

  normalized.push({
    json: {
      id: "lever:" + site + ":" + String(job.id),
      company,
      title,
      location,
      description: description
        .replace(/<[^>]*>/g, " ")
        .replace(/\s+/g, " ")
        .trim()
        .slice(0, 8000),
      url,
      source: "Lever",
      status: "Needs review"
    }
  });
}

// Keep the branch available even if no jobs match.
return normalized.length
  ? normalized
  : [{ json: { skip: true, source: "Lever" } }];

