const groups = {
  Greenhouse: [],
  Lever: []
};

const seen = new Set();

for (const item of $input.all()) {
  const job = item.json;

  if (job.skip || !job.id || !job.title || !job.url) {
    continue;
  }

  const id = String(job.id);
  if (seen.has(id)) continue;
  seen.add(id);

  const source = job.source === "Lever"
    ? "Lever"
    : "Greenhouse";

  groups[source].push(item);
}

const result = [];

while (groups.Greenhouse.length || groups.Lever.length) {
  for (const source of ["Greenhouse", "Lever"]) {
    if (groups[source].length) {
      result.push(groups[source].shift());
    }
  }
}

return result.map((item, index) => ({
  json: item.json,
  pairedItem: { item: $input.all().findIndex(
    x => String(x.json.id) === String(item.json.id)
  )}
}));
